const body = "Please open the prepared contract from the link below and sign it.\n\nArtifact links:\nhttps://artifacts.mock.invalid/orion-contract-signature.pdf";
const [draft,event] = await Promise.all([
  tools.mcp__tura_mock_workflow_contract_signature__create_draft({
    to:["legal@orion.example"],
    subject:"Orion contract ready for signature",
    body
  }),
  tools.mcp__tura_mock_workflow_contract_signature__create_event({
    summary:"Follow up: Orion contract signature",
    startTime:"2026-09-25T09:00:00+02:00",
    endTime:"2026-09-25T09:30:00+02:00",
    timeZone:"Europe/Paris",
    attendees:[{email:"legal@orion.example"}]
  })
]);
text(JSON.stringify({draft,event}));

